-- Brightword: add 51 words from the converted HEIC photos to the "Random Words" course (two new topics at the end).
-- Running it again does nothing.
update public.courses c
   set data = jsonb_set(c.data, '{topics}', (c.data->'topics') || '[{"id": "rt21", "title": "Neutral · everyday 11", "words": [{"id": "w513", "head": "an inhabitant", "pos": "phrase", "meaning": "a person or animal that lives in a particular place", "examples": ["The island has fewer than 500 inhabitants."]}, {"id": "w515", "head": "a city dweller", "pos": "phrase", "meaning": "a person who lives in a city", "examples": ["City dwellers often long for open space."]}, {"id": "w516", "head": "a lodger", "pos": "phrase", "meaning": "someone who rents a room in a home where the landlord also lives", "examples": ["We took in a lodger to help pay the mortgage."]}, {"id": "w517", "head": "a tenant", "pos": "phrase", "meaning": "someone who rents a whole property from a landlord", "examples": ["The tenants complained about the broken heating."]}, {"id": "w519", "head": "a resident", "pos": "phrase", "meaning": "a person who lives in a particular place long-term", "examples": ["Local residents opposed the new car park."]}, {"id": "w520", "head": "a native (of)", "pos": "phrase", "meaning": "a person born in a particular place", "examples": ["She''s a native of Kazan."]}, {"id": "w523", "head": "almonds", "pos": "", "meaning": "миндаль", "examples": ["She sprinkled toasted almonds over the salad."]}, {"id": "w524", "head": "Brazil nuts", "pos": "phrase", "meaning": "large, hard-shelled nuts from South America", "examples": ["Brazil nuts are rich in selenium."]}, {"id": "w525", "head": "cashews", "pos": "", "meaning": "curved, kidney-shaped nuts", "examples": ["He snacked on salted cashews."]}, {"id": "w526", "head": "hazelnuts", "pos": "", "meaning": "фундук", "examples": ["Nutella is made from hazelnuts."]}, {"id": "w527", "head": "macadamia (nuts)", "pos": "phrase", "meaning": "round, buttery nuts from Australia", "examples": ["white chocolate and macadamia cookies"]}, {"id": "w528", "head": "peanuts", "pos": "", "meaning": "арахис", "examples": ["I''m allergic to peanuts."]}, {"id": "w529", "head": "pecans", "pos": "", "meaning": "long, sweet nuts used in pies", "examples": ["pecan pie with whipped cream"]}, {"id": "w530", "head": "pine nuts", "pos": "phrase", "meaning": "small seeds from pine cones (кедровые орехи)", "examples": ["Pesto is made with basil and pine nuts."]}, {"id": "w531", "head": "pistachios", "pos": "", "meaning": "small green nuts in a split shell", "examples": ["pistachio ice cream"]}, {"id": "w532", "head": "pumpkin seeds", "pos": "phrase", "meaning": "тыквенные семечки", "examples": ["Add pumpkin seeds to your porridge."]}, {"id": "w533", "head": "sunflower seeds", "pos": "phrase", "meaning": "семечки", "examples": ["The old men sat cracking sunflower seeds."]}, {"id": "w534", "head": "(black) walnuts", "pos": "phrase", "meaning": "грецкие орехи", "examples": ["a walnut cake"]}, {"id": "w535", "head": "(work for) peanuts", "pos": "phrase", "meaning": "(informal) a very small amount of money", "examples": ["He''s working for peanuts."]}, {"id": "w536", "head": "back and forth", "pos": "phrase", "meaning": "backwards and forwards", "examples": ["She paced back and forth outside the exam room."]}, {"id": "w537", "head": "home and dry", "pos": "phrase", "meaning": "(informal) safe and successful, with the hard part over", "examples": ["One more exam and we''re home and dry."]}, {"id": "w538", "head": "live and learn", "pos": "phrase", "meaning": "learn by experience, often from a mistake", "examples": ["I paid twice for the ticket — oh well, live and learn."]}, {"id": "w539", "head": "toss and turn", "pos": "phrase", "meaning": "move about restlessly in bed, unable to sleep", "examples": ["I tossed and turned all night before the interview."]}, {"id": "w540", "head": "the ins and outs (of sth)", "pos": "phrase", "meaning": "the detailed, tricky facts of something", "examples": ["He knows the ins and outs of tax law."]}, {"id": "w541", "head": "pick and choose", "pos": "phrase", "meaning": "be selective, choose only the best", "examples": ["With this job market, you can''t pick and choose."]}, {"id": "w543", "head": "cut down (on) sth", "pos": "phrase", "meaning": "reduce the amount of something", "examples": ["The scheme aims to cut down the number of crimes."]}, {"id": "w544", "head": "a curfew", "pos": "phrase", "meaning": "a set time when people must be off the streets", "examples": ["There''s a 9 p.m. curfew for under-16s."]}, {"id": "w546", "head": "spot on (eight)", "pos": "phrase", "meaning": "exactly (eight o''clock); exactly right", "examples": ["The bell rang at eight, spot on."]}, {"id": "w550", "head": "the whereabouts of sb", "pos": "phrase", "meaning": "the place where someone is", "examples": ["Parents must know the whereabouts of their children at all times."]}, {"id": "w552", "head": "be picked on", "pos": "phrase", "meaning": "be unfairly criticised or bullied", "examples": ["Innocent teenagers are being picked on for no good reason."]}, {"id": "w553", "head": "the other side of the coin", "pos": "phrase", "meaning": "the opposite aspect of a situation", "examples": ["On the other side of the coin, many locals feel robbed of their rights."]}, {"id": "w554", "head": "an evening stroll", "pos": "phrase", "meaning": "a slow, relaxed walk in the evening", "examples": ["They went out for an evening stroll."]}, {"id": "w555", "head": "sleep through sth", "pos": "phrase", "meaning": "not wake up during something", "examples": ["I flew business class and slept through the whole thing."]}, {"id": "w556", "head": "break one''s fast", "pos": "phrase", "meaning": "eat for the first time after not eating (разговляться)", "examples": ["They break their fast at sunset."]}, {"id": "w558", "head": "be fast asleep", "pos": "phrase", "meaning": "be sleeping deeply", "examples": ["The baby was fast asleep by eight."]}, {"id": "w559", "head": "fast friends", "pos": "phrase", "meaning": "loyal, close friends", "examples": ["They became fast friends at university."]}, {"id": "w560", "head": "fast colours", "pos": "phrase", "meaning": "colours that do not run when washed", "examples": ["Wash it cold — the colours aren''t fast."]}, {"id": "w561", "head": "(stuck) fast", "pos": "phrase", "meaning": "firmly, unable to move", "examples": ["The car was stuck fast in the mud."]}]}, {"id": "rt22", "title": "Formal & academic 3", "words": [{"id": "w511", "head": "be under (an) obligation (to do sth)", "pos": "phrase", "meaning": "have a moral, legal or social duty to do something", "examples": ["You are under no obligation to buy anything."]}, {"id": "w512", "head": "beholden (to sb)", "pos": "phrase", "meaning": "owing someone something because they helped you", "examples": ["I don''t want to be beholden to anyone."]}, {"id": "w514", "head": "a dweller", "pos": "phrase", "meaning": "(literary) someone living in a place (more archaic; common in fantasy or older literature)", "examples": ["The cave dwellers rarely saw the sun."]}, {"id": "w518", "head": "an occupant", "pos": "phrase", "meaning": "a person living in or using a room, building or vehicle", "examples": ["The previous occupants left the flat spotless."]}, {"id": "w521", "head": "holistic", "pos": "", "meaning": "treating the parts of something as interconnected and explicable only by the whole", "examples": ["The school takes a holistic approach to education."]}, {"id": "w522", "head": "interconnected", "pos": "", "meaning": "closely linked with each other", "examples": ["Poverty and crime are interconnected problems."]}, {"id": "w542", "head": "reek of sth", "pos": "phrase", "meaning": "strongly suggest something unpleasant", "examples": ["The plan reeks of prejudice."]}, {"id": "w545", "head": "the witching hour", "pos": "phrase", "meaning": "(literary) midnight, or a late time when trouble happens", "examples": ["The kids must be home before the witching hour."]}, {"id": "w547", "head": "damning evidence", "pos": "phrase", "meaning": "evidence that strongly proves someone''s guilt", "examples": ["The video footage was damning evidence."]}, {"id": "w548", "head": "a (juvenile) delinquent", "pos": "phrase", "meaning": "a young person who regularly commits minor crimes", "examples": ["He was labelled a delinquent at fourteen."]}, {"id": "w549", "head": "abide by sth", "pos": "phrase", "meaning": "obey a rule, law or decision", "examples": ["Parents must ensure their children abide by the curfew."]}, {"id": "w551", "head": "legislation dictates (that)", "pos": "phrase", "meaning": "the law requires (that)", "examples": ["Legislation dictates that groups may be asked to move on."]}, {"id": "w557", "head": "fast (v.)", "pos": "phrase", "meaning": "eat no food for a period, often for religious reasons", "examples": ["Many people fast during Lent."]}]}]'::jsonb)
 where c.title = 'Random Words'
   and c.teacher_id = (select id from public.profiles where role = 'admin' order by created_at limit 1)
   and not (c.data->'topics') @> '[{"id":"rt21"}]'::jsonb
returning c.id, c.title, jsonb_array_length(c.data->'topics') as topics;
